  "content": "import os
import subprocess
import sys

import pytest

from click.shell_completion import BashComplete


@pytest.fixture
def mock_cli():
    from click import BaseCommand
    return type('MockCLI', (BaseCommand,), {})()


def test_bash_version_with_parens(mock_cli):
    """Bash version with parentheses like '5.2.12(1)-release' should not cause
    syntax error in subprocess call."""
    # Simulate a BASH_VERSION that includes parentheses, typical on Windows Git Bash.
    fake_version = "5.2.12(1)-release"
    # We need to stub subprocess.run in BashComplete._check_version to test the
    # parsing. We'll replace it for the duration of this test.
    original_run = subprocess.run
    try:
        def fake_run(cmd, **kwargs):
            # Ensure the command is correctly quoted
            assert cmd == ["bash", "-c", 'echo "${BASH_VERSION}"']
            class FakeCompletedProcess:
                stdout = fake_version.encode()
                def __init__(self, **kwargs):
                    pass
            return FakeCompletedProcess(stdout=fake_version.encode())
        subprocess.run = fake_run
        # Create BashComplete instance with dummy arguments
        comp = BashComplete(mock_cli, {}, "test", "COMPLETE")
        # This should not raise RuntimeError about version detection
        comp._check_version()
    finally:
        subprocess.run = original_run


def test_bash_version_still_fails_on_unparseable(mock_cli):
    """If bash version output is not parseable, should still raise RuntimeError."""
    original_run = subprocess.run
    try:
        def fake_run(cmd, **kwargs):
            class FakeCompletedProcess:
                stdout = b"garbage output"
                def __init__(self, **kwargs):
                    pass
            return FakeCompletedProcess()
        subprocess.run = fake_run
        comp = BashComplete(mock_cli, {}, "test", "COMPLETE")
        with pytest.raises(RuntimeError, match="Couldn't detect Bash version"):
            comp._check_version()
    finally:
        subprocess.run = original_run
